using System.Windows;using System.Windows.Controls;using Microsoft.Win32;using MizanDesktop.Services;
namespace MizanDesktop.Views;
public partial class EnterpriseView:UserControl{readonly EnterpriseAccountingService svc=new();public EnterpriseView(){InitializeComponent();From.SelectedDate=DateTime.Today.AddMonths(-1);To.SelectedDate=DateTime.Today;Refresh_Click(null,null);}void Refresh_Click(object? s,RoutedEventArgs? e){var x=svc.Financials(From.SelectedDate!.Value,To.SelectedDate!.Value.AddDays(1));Sales.Text=x.Sales.ToString("N2");Cogs.Text=x.Cogs.ToString("N2");Gross.Text=x.GrossProfit.ToString("N2");Net.Text=x.NetProfit.ToString("N2");Trial.ItemsSource=svc.TrialBalance();Parties.ItemsSource=svc.PartyBalances();}void CloseCash_Click(object s,RoutedEventArgs e){var v=DialogService.Prompt("إغلاق الصندوق","أدخل الرصيد الفعلي للصندوق الرئيسي SYP");if(decimal.TryParse(v,out var a)){svc.CloseCash("MAIN-SYP",a,App.CurrentUser?.Name??"admin");MessageBox.Show("تم إغلاق الصندوق وتسجيل الفرق.");}}void CancelInvoice_Click(object s,RoutedEventArgs e){var v=DialogService.Prompt("إلغاء فاتورة","أدخل معرّف الفاتورة GUID");if(Guid.TryParse(v,out var id)){try{svc.CancelInvoice(id,App.CurrentUser?.Name??"admin","إلغاء يدوي");MessageBox.Show("تم الإلغاء وإنشاء القيد العكسي.");Refresh_Click(null,null);}catch(Exception ex){MessageBox.Show(ex.Message);}}}void Import_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="SQLite (*.db;*.sqlite)|*.db;*.sqlite|All files|*.*"};if(d.ShowDialog()==true){try{var report=svc.ImportAndroid(d.FileName);MessageBox.Show(report.ToString(),"اكتمل استيراد Android");}catch(Exception ex){MessageBox.Show(ex.Message);}}}}
